// Zoom map, a PROTOTYPE (GEO 11-27; Ryan 11-07): a map of the contiguous states; click a state (or pick it from the list) to zoom
// into its counties, and go back out. Hidden page #/labs/map, reachable only for an account whose per-account switch zoomMap is on
// (assets/app-library.js routes it; there is no top-bar entry). Static: the shapes and the one value (the Census Bureau's population
// estimates) ship as same-origin script files (the CSP's connect-src is Supabase only), generated by tools/zoom-map/export_zoom_map.py.
// The states file loads when the page opens; a state's county file loads only when that state is chosen. SVG is built with
// createElementNS and colours are attributes (the CSP allows no inline style; assets/zoom-map.css holds the rest).
// Every number says estimated, observed or calculated. All public words here are DRAFT, FOR RYAN'S YES.
(() => {
  const NS = 'http://www.w3.org/2000/svg';
  const VERSION = '20261127zm1';                 // the ?v= of every data file; equals the data's own version (tests/zoom-map.test.mjs)
  const FILL = ['#dfe6f3', '#b3c2e0', '#8299c7', '#55699f', '#2f3f73'];      // pale to dark blue, as on the Perfect City page
  const NO_DATA = '#4a4a52';
  const WORDS = {
    intro: 'Click a state, or pick it from the list, to zoom into its counties. Click a county to see its number. Use Back to all states to zoom out.',
    usHint: 'Pick a state to zoom in.',
    notDone: ['No animation over time yet: one date only (July 1, 2024).',
      'One value only: total population. No other measures yet.',
      'Contiguous states and the District of Columbia only. Alaska and Hawaii (insets) and Puerto Rico are not drawn yet.',
      'Shapes are simplified for speed, so small islands are left out and borders are approximate.',
      'Colours compare places at the same level only: states with states, and a state\'s counties with each other.'],
    loadError: 'The map data could not be loaded. Try again later.',
    countyError: (name) => `The counties of ${name} could not be loaded. You are back on the whole map.`,
    smallStates: 'Small states: pick them from the State list.'
  };
  const fmt = (n) => Math.round(n).toLocaleString('en-US');

  // Quantile cut points (up to 4) for 5 colour bands; duplicates collapse, so a few values give fewer bands.
  function breaks(values) {
    const v = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
    if (!v.length) return [];
    const out = [];
    for (let i = 1; i < FILL.length; i++) {
      const b = v[Math.min(v.length - 1, Math.floor((i * v.length) / FILL.length))];
      if (b > v[0] && !out.includes(b)) out.push(b);
    }
    return out;
  }
  function band(value, br) {
    if (!Number.isFinite(value)) return -1;
    let i = 0;
    while (i < br.length && value >= br[i]) i++;
    return Math.min(i, FILL.length - 1);
  }
  // A viewBox around bbox [x0, y0, x1, y1] with a margin, kept to the frame's own w:h shape so nothing stretches.
  function fitBox(bbox, w, h, margin = 0.08) {
    let bw = bbox[2] - bbox[0], bh = bbox[3] - bbox[1];
    const cx = (bbox[0] + bbox[2]) / 2, cy = (bbox[1] + bbox[3]) / 2;
    bw *= 1 + 2 * margin; bh *= 1 + 2 * margin;
    if (bw / bh > w / h) bh = bw * h / w; else bw = bh * w / h;
    return [cx - bw / 2, cy - bh / 2, bw, bh].map((x) => +x.toFixed(2));
  }

  function loadScript(src, have) {
    if (have()) return Promise.resolve(have());
    return new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = () => (have() ? resolve(have()) : reject(new Error('no data')));
      s.onerror = () => { s.remove(); reject(new Error('no data')); };      // a retry adds a fresh tag
      document.head.append(s);
    });
  }
  const loadStates = () => loadScript(`/assets/zoom-map/states.js?v=${VERSION}`, () => window.ryagramZoomMapData && window.ryagramZoomMapData.us);
  const loadCounties = (fp) => {
    if (!/^\d{2}$/.test(fp)) return Promise.reject(new Error('no data'));
    return loadScript(`/assets/zoom-map/st-${fp}.js?v=${VERSION}`, () => window.ryagramZoomMapCounties && window.ryagramZoomMapCounties[fp]);
  };

  function svg(tag, attrs = {}, kids = []) {
    const el = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) if (v != null) el.setAttribute(k, String(v));
    for (const c of kids) el.append(c);
    return el;
  }
  const titled = (el, text) => { el.append(svg('title', {}, [text])); return el; };

  async function view({ h }) {
    const status = h('p', { class: 'form-note', id: 'zm-status', role: 'status' }, 'Loading...');
    let us;
    try { us = await loadStates(); } catch { status.textContent = WORDS.loadError; return [h('h1', { tabindex: '-1' }, 'Zoom map (prototype)'), status]; }
    status.textContent = '';
    const byId = new Map(us.states.map((s) => [s.id, s]));
    const state = { fp: null, county: null, counties: null };
    const usBreaks = breaks(us.states.map((s) => s.pop));
    const usBox = [0, 0, us.width, us.height];

    const root = svg('svg', { viewBox: usBox.join(' '), class: 'zm-svg', id: 'zm-svg', role: 'img', 'aria-label': 'Map of the contiguous United States, states shaded by population (estimated)' });
    const gStates = svg('g', { class: 'zm-states' });
    const gCounties = svg('g', { class: 'zm-counties' });
    root.append(gStates, gCounties);
    const area = (s) => (s.bbox[2] - s.bbox[0]) * (s.bbox[3] - s.bbox[1]);
    for (const s of [...us.states].sort((a, b) => area(b) - area(a))) {      // biggest first, so a small state (DC, RI, DE) is drawn on top and wins the tap
      const p = svg('path', { d: s.d, fill: FILL[band(s.pop, usBreaks)] || NO_DATA, class: 'zm-state', 'data-id': s.id, 'fill-rule': 'evenodd' });
      titled(p, `${s.name}: ${s.pop == null ? 'no figure' : fmt(s.pop) + ' people (estimated)'}`);
      p.addEventListener('click', () => { if (state.fp !== s.id) zoomTo(s.id); });
      gStates.append(p);
    }

    const stateSel = h('select', { id: 'zm-state', onchange: (e) => (e.target.value ? zoomTo(e.target.value, { fromList: true }) : backOut()) },
      h('option', { value: '' }, 'All states (whole map)'), us.states.map((s) => h('option', { value: s.id }, s.name)));
    const countyWrap = h('span', { class: 'zm-county-wrap', id: 'zm-county-wrap' });
    const back = h('button', { class: 'button secondary', type: 'button', id: 'zm-back', hidden: true, onclick: () => { backOut(); stateSel.focus(); } }, '← Back to all states');      // the button hides itself, so focus goes to the list
    const controls = h('div', { class: 'zm-controls' }, h('label', { class: 'zm-control', for: 'zm-state' }, 'State ', stateSel), countyWrap, back);
    const legend = h('div', { class: 'zm-legend', id: 'zm-legend' });
    const detail = h('div', { class: 'zm-detail', id: 'zm-detail', 'aria-live': 'polite' });
    const retry = h('button', { class: 'button secondary', type: 'button', id: 'zm-retry', hidden: true }, 'Try again');
    const mapBox = h('div', { class: 'zm-map', id: 'zm-map' }, root, legend);

    function drawLegend(values, scope, unit) {
      const br = breaks(values);
      const n = br.length + 1;
      const distinct = [...new Set(values.filter((x) => Number.isFinite(x)))].sort((a, b) => a - b);
      const each = n > 1 && n === distinct.length;    // a few places: one band per place, so the key shows each value itself
      const label = (i) => (each ? fmt(distinct[i]) : n === 1 ? 'all' : i === 0 ? `under ${fmt(br[0])}` : i === n - 1 ? `${fmt(br[i - 1])} or more` : `${fmt(br[i - 1])} to under ${fmt(br[i])}`);
      const keys = Array.from({ length: n }, (_, i) => h('li', {}, h('span', { class: 'zm-swatch', 'data-fill': FILL[i] }), ' ', label(i)));
      const finite = values.filter((x) => Number.isFinite(x)).length;
      const how = each ? `one band per ${distinct.length === finite ? unit : 'value'}` : n === 1 ? 'one band' : 'about one fifth in each';
      legend.replaceChildren(h('p', { class: 'meta' }, `${us.value.name} (estimated, ${us.value.date})`), h('ul', { class: 'zm-keys' }, keys),
        h('p', { class: 'meta', id: 'zm-bands' }, `Bands (calculated): ${scope}, ${how}.`), h('p', { class: 'meta' }, 'Grey: no published figure.'));
      legend.querySelectorAll('.zm-swatch').forEach((s) => s.replaceChildren(svg('svg', { width: 14, height: 14, 'aria-hidden': 'true' }, [svg('rect', { width: 14, height: 14, fill: s.getAttribute('data-fill') })])));
    }

    function drawDetail() {
      const s = state.fp && byId.get(state.fp);
      if (!s) { detail.replaceChildren(h('p', { class: 'form-intro' }, WORDS.usHint)); return; }
      const out = [h('h2', { id: 'zm-place' }, s.name),
        h('ul', { class: 'zm-facts' },
          h('li', {}, `People: ${s.pop == null ? 'no figure' : fmt(s.pop)}`, h('span', { class: 'zm-label' }, ' estimated, July 1, 2024')),
          h('li', {}, `Counties and county equivalents: ${s.counties}`, h('span', { class: 'zm-label' }, ' observed, 2024 boundary file')))];
      const c = state.county && state.counties && state.counties.counties.find((x) => x.id === state.county);
      if (c) {
        out.push(h('h3', { id: 'zm-county-name' }, c.name),
          h('ul', { class: 'zm-facts', id: 'zm-county-facts' },
            h('li', {}, `People: ${c.pop == null ? 'no figure' : fmt(c.pop)}`, c.pop == null ? null : h('span', { class: 'zm-label' }, ' estimated, July 1, 2024')),
            c.pop != null && s.pop ? h('li', {}, `Share of ${s.name}: ${(100 * c.pop / s.pop).toFixed(1)}%`, h('span', { class: 'zm-label' }, ' calculated')) : null,
            h('li', { class: 'meta' }, `County code (FIPS) ${c.id}`)));
      } else out.push(h('p', { class: 'meta' }, 'Click a county, or pick it from the list, to see its number.'));
      detail.replaceChildren(...out);
    }

    function pickCounty(id) {
      state.county = id || null;
      gCounties.querySelectorAll('path').forEach((p) => p.classList.toggle('zm-picked', p.getAttribute('data-id') === state.county));
      const sel = countyWrap.querySelector('select');
      if (sel) sel.value = state.county || '';
      drawDetail();
    }

    async function zoomTo(fp, { fromList = false } = {}) {
      const s = byId.get(fp);
      if (!s) return;
      state.fp = fp; state.county = null; state.counties = null;
      stateSel.value = fp;
      retry.hidden = true;
      gCounties.replaceChildren();                    // the last state's counties go at once: never two states on screen
      countyWrap.replaceChildren();
      drawDetail();
      status.textContent = 'Loading the counties...';
      let data;
      try { data = await loadCounties(fp); } catch {
        if (state.fp !== fp) return;
        backOut();                                    // a clean whole map, and this state is no longer current, so a click or the list retries
        status.textContent = WORDS.countyError(s.name);
        retry.onclick = () => { stateSel.focus(); zoomTo(fp); };      // the button hides itself, so focus goes to the list
        retry.hidden = false;
        return;
      }
      if (state.fp !== fp) return;                    // another state was chosen while this one loaded
      state.counties = data;
      status.textContent = '';
      const br = breaks(data.counties.map((c) => c.pop));
      gCounties.replaceChildren(...data.counties.map((c) => {
        const p = svg('path', { d: c.d, fill: FILL[band(c.pop, br)] || NO_DATA, class: 'zm-county', 'data-id': c.id, 'fill-rule': 'evenodd' });
        p.addEventListener('click', () => pickCounty(c.id));
        return titled(p, `${c.name}: ${c.pop == null ? 'no figure' : fmt(c.pop) + ' people (estimated)'}`);
      }));
      gStates.querySelectorAll('path').forEach((p) => p.classList.toggle('zm-dim', p.getAttribute('data-id') !== fp));
      root.setAttribute('viewBox', fitBox(s.bbox, us.width, us.height).join(' '));
      root.setAttribute('aria-label', `Map of ${s.name}: ${data.counties.length} counties shaded by population (estimated)`);
      root.classList.add('zm-zoomed');
      const csel = h('select', { id: 'zm-county', onchange: (e) => pickCounty(e.target.value) },
        h('option', { value: '' }, `All of ${s.name}`), [...data.counties].sort((a, b) => a.name.localeCompare(b.name)).map((c) => h('option', { value: c.id }, c.name)));
      countyWrap.replaceChildren(h('label', { class: 'zm-control', for: 'zm-county' }, 'County ', csel));
      back.hidden = false;
      drawLegend(data.counties.map((c) => c.pop), `the counties of ${s.name} only`, 'county');
      drawDetail();
      // On a phone the map can sit below the fold after a pick from the list: bring it into view.
      if (fromList && window.matchMedia && window.matchMedia('(max-width: 700px)').matches) root.scrollIntoView({ block: 'nearest' });
    }

    function backOut() {
      state.fp = null; state.county = null; state.counties = null;
      stateSel.value = '';
      status.textContent = '';
      retry.hidden = true;
      gCounties.replaceChildren();
      gStates.querySelectorAll('path').forEach((p) => p.classList.remove('zm-dim'));
      root.setAttribute('viewBox', usBox.join(' '));
      root.setAttribute('aria-label', 'Map of the contiguous United States, states shaded by population (estimated)');
      root.classList.remove('zm-zoomed');
      countyWrap.replaceChildren();
      back.hidden = true;
      drawLegend(us.states.map((s) => s.pop), 'the states on this map', 'state');
      drawDetail();
    }
    backOut();

    const src = us.sources;
    return [h('h1', { tabindex: '-1' }, 'Zoom map (prototype)'), h('p', { class: 'form-intro' }, WORDS.intro), controls, status, retry, mapBox,
      h('p', { class: 'meta', id: 'zm-small' }, WORDS.smallStates), detail,
      h('h2', {}, 'What this prototype does not do'), h('ul', { class: 'soon-more', id: 'zm-not-done' }, WORDS.notDone.map((t) => h('li', {}, t))),
      h('p', { class: 'meta', id: 'zm-sources' }, `Sources: ${src.boundaries}; ${src.values}. ${src.calculated} Map projection: ${us.projection}.`),
      h('p', { class: 'form-note', role: 'note' }, 'Prototype. Draft wording, not yet approved.')];
  }

  window.ryagramZoomMap = Object.freeze({ view, breaks, band, fitBox, VERSION, WORDS });
})();
